</script>
<template><main class="page"><div class="content"><header><div><p class="eyebrow">S104 · TEAM INFORMATION</p><h1>团队信息</h1><p>{{ info.task?.title||'任务团队' }}</p></div><StatusTag v-if="info.task" :status="info.task.status" /></header><section v-if="!info.success" class="warning"><strong>{{ info.message }}</strong><p>未选中学生只能查看报名结果，不能查看完整团队信息。</p></section><template v-else><section class="card"><h2>团队概览</h2><dl><div><dt>任务名称</dt><dd>{{ info.task.title }}</dd></div><div><dt>指导老师</dt><dd>{{ info.task.advisorName }}</dd></div><div><dt>队长姓名</dt><dd>{{ info.leader?.studentName||info.task.leaderName||'--' }}</dd></div><div><dt>队长学号</dt><dd>{{ info.leader?.studentId||info.task.leaderId||'--' }}</dd></div><div><dt>任务当前状态</dt><dd><StatusTag :status="info.task.status" /></dd></div></dl></section><section class="card"><h2>团队成员</h2><div class="table-wrap"><table><thead><tr><th>成员姓名</th><th>学号</th><th>角色</th><th>学院</th><th>专业</th></tr></thead><tbody><tr v-for="member in info.members" :key="member.studentId"><td>{{ member.studentName }}</td><td>{{ member.studentId }}</td><td><StatusTag :status="member.isLeader?'confirmed':'accepted'" :text="member.isLeader?'队长':'成员'" /></td><td>{{ member.college||'--' }}</td><td>{{ member.major||'--' }}</td></tr></tbody></table></div></section></template><div class="actions"><button @click="back">返回我的任务</button></div></div></main></template>
